package com.cratesmp.crateshop.command;
import com.cratesmp.crateshop.CRATEShop; import com.cratesmp.crateshop.gui.ShopMenu; import com.cratesmp.crateshop.listener.ShopListener; import com.cratesmp.crateshop.shop.ShopManager; import org.bukkit.ChatColor; import org.bukkit.Location; import org.bukkit.command.*; import org.bukkit.entity.Player; import org.bukkit.entity.Villager; import org.bukkit.persistence.PersistentDataType; import java.util.*;
public final class CrateShopCommand implements TabExecutor {private final CRATEShop plugin;private final ShopMenu menu;private final ShopManager manager;public CrateShopCommand(CRATEShop p,ShopMenu m,ShopManager s){plugin=p;menu=m;manager=s;}
 public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(a.length==0){if(s instanceof Player p)menu.open(p);else s.sendMessage("/crateshop reload | /crateshop npc");return true;}if(!s.hasPermission("crateshop.admin")){s.sendMessage("§cNo permission.");return true;}if(a[0].equalsIgnoreCase("reload")){plugin.reloadShop();s.sendMessage("§aCRATEShop ricaricato.");return true;}if(a[0].equalsIgnoreCase("npc")){if(!(s instanceof Player p)){s.sendMessage("Players only.");return true;}spawn(p);return true;}s.sendMessage("§e/crateshop reload §7- reload config\n§e/crateshop npc §7- spawn shop NPC");return true;}
 private void spawn(Player p){Location loc=p.getLocation();Villager v=p.getWorld().spawn(loc,Villager.class);v.setAI(false);v.setInvulnerable(true);v.setCollidable(false);v.setProfession(Villager.Profession.ARMORER);v.customName(ChatColor.translateAlternateColorCodes('&',plugin.getConfig().getString("settings.npc-name","&6&lCRATE SHOP")));v.setCustomNameVisible(true);v.getPersistentDataContainer().set(new org.bukkit.NamespacedKey(plugin,"shop_npc"),PersistentDataType.BYTE,(byte)1);p.sendMessage("§aNPC Shop creato! Cliccalo con il tasto destro.");}
 public List<String> onTabComplete(CommandSender s,Command c,String a,String[] args){if(args.length==1)return List.of("reload","npc");return List.of();}}
